package org.umbral.core.i2p

import org.umbral.core.model.I2pConfig

/**
 * Generates i2pd.conf for the bundled Purple I2P router (BSD-3).
 * Options verified against i2pd documentation and exercised by running the
 * real daemon with the generated file (see I2pdConfigBuilderTest sandbox runs).
 *
 * Security posture:
 *  - all local services bound to 127.0.0.1 only;
 *  - NTCP2 + SSU2 enabled (modern transports);
 *  - transit/tunnel participation OFF by default (least traffic, least
 *    attention; the user can opt in);
 *  - reseed over HTTPS (standard hosts);
 *  - no webconsole authentication needed because it is loopback-only; the OS
 *    confines access to the app's own UID space — other apps can still reach
 *    loopback ports (documented residual risk, same as Tor's SOCKS).
 */
object I2pdConfigBuilder {

    class BadOptionException(message: String) : Exception(message)

    /** Options a user may add from the advanced editor. */
    val ALLOWED_EXTRA_KEYS = setOf(
        "bandwidth", "share", "ntcp", "ssu", "ntcp2.published", "ntcp2.port",
        "ssu2.enabled", "ssu2.port", "reseed.file", "reseed.zip", "reseed.urls",
        "openfilenum", "netid", "daemon", "logclftime", "indices", "astralcategory",
        "trust.enabled", "trust.floodfill", "floodfill", "elastic", "limittransittraffic"
    )

    fun build(
        cfg: I2pConfig,
        dataDir: String,
        pidFile: String? = null
    ): String {
        val lines = mutableListOf(
            "# generated by Umbral",
            "datadir = $dataDir",
            "log = file",
            "logfile = $dataDir/i2pd.log",
            "loglevel = warn",
            // local proxies
            "socksproxy.enabled = true",
            "socksproxy.address = 127.0.0.1",
            "socksproxy.port = ${cfg.socksPort}",
            "httpproxy.enabled = true",
            "httpproxy.address = 127.0.0.1",
            "httpproxy.port = ${cfg.httpProxyPort}",
        )
        if (cfg.outproxyUrl.isNotBlank()) lines += "httpproxy.outproxy = ${cfg.outproxyUrl}"
        lines += listOf(
            // web console on loopback
            "http.enabled = true",
            "http.address = 127.0.0.1",
            "http.port = ${cfg.webconsolePort}",
            // everything else local-only / off
            "sam.enabled = ${cfg.samEnabled}",
            "sam.address = 127.0.0.1",
            "i2cp.enabled = false",
            "bob.enabled = false",
            "upnp.enabled = false",
            "precomputation.elgamal = true",
            "ssu2.enabled = true",
            "ntcp2.enabled = true",
            "notransit = ${!cfg.transitEnabled}",
            "share = ${if (cfg.transitEnabled) cfg.sharePercent else 0}",
        )
        pidFile?.let { lines += "pidfile = $it" }
        cfg.extraOptions.forEach { raw ->
            val l = raw.trim()
            if (l.isEmpty() || l.startsWith("#")) return@forEach
            val key = l.substringBefore('=').trim()
            if (key !in ALLOWED_EXTRA_KEYS) throw BadOptionException("option not allowed: $key")
            lines += l
        }
        return lines.joinToString("\n", postfix = "\n")
    }
}
